function w11Est(s){try{return estimateRange({cat:s.cat||"Handyman",size:s.size||"medium",urg:s.urg==="emergency"?"emergency":s.urg==="urgent"?"urgent":s.urg==="flexible"?"flexible":"soon",zip:s.zip,desc:(s.title||"")+" "+(s.desc||"")})}catch(e){return null}}
function w11Match(j,n){const zip=j.zip;return PROS().filter(u=>u.trade===j.cat).map(u=>{const r=rating(u.id),d=dist(zip,u.zip),rp=isRapid(u.id);let s=(r.n?r.avg*10+Math.min(r.n,40)/4:28)-d/3+(u.verified?8:0)+(rp?(j.urgent?14:5):0)+(u.availNow?4:0)+(j.sub&&(u.subs||[]).includes(j.sub)?6:0);
 const why=[];if(j.sub&&(u.subs||[]).includes(j.sub))why.push("Does "+j.sub.toLowerCase());if(u.verified)why.push("License + insurance checked");if(rp)why.push("Replies in under an hour");if(d<=15)why.push(d+" mi away");if(u.availNow)why.push("Available now");return{u,r,d,s,why}}).filter(x=>x.d<=Math.max(+x.u.radius||40,40)).sort((a,b)=>b.s-a.s).slice(0,n||3)}
