 f.querySelectorAll("[data-cat]").forEach(b=>b.onclick=()=>{if(s.cat!==b.dataset.cat){s.cat=b.dataset.cat;s.sub="";}step(1)});
 const al=$("w11all");if(al)al.onchange=()=>{if(al.value){s.cat=al.value;s.sub="";step(1)}};
 const qi=$("w11q");if(qi){const sg=$("w11sug");const up=()=>{s.q=qi.value;keep();const r=qi.value.trim().length>2?smart(qi.value):[];sg.innerHTML=r.slice(0,4).map(x=>`<button type="button" class="w11-sg" data-sc="${esc(x.cat)}" data-ss="${esc(x.sub)}">${I(TRADE_ICON[x.cat]||"wrench",14)}<b>${esc(x.cat)}</b> › ${esc(x.sub)}</button>`).join("")||(qi.value.trim().length>2?`<span class="small muted">No exact match. Pick the closest trade below, or Handyman.</span>`:"");
  sg.querySelectorAll("[data-sc]").forEach(b=>b.onclick=()=>{s.cat=b.dataset.sc;s.sub=b.dataset.ss;if(!s.title)s.title=b.dataset.ss;if(!s.desc)s.desc=qi.value.trim().replace(/^./,c=>c.toUpperCase());step(1)})};qi.oninput=up;if(qi.value)up()}
 f.querySelectorAll("[data-sub]").forEach(b=>b.onclick=()=>{pull();const was=s.sub;s.sub=s.sub===b.dataset.sub?"":b.dataset.sub;if(!s.title||s.title===was)s.title=s.sub;keep();const y=scrollY;render();scrollTo(0,y)});
 f.querySelectorAll("[data-goto]").forEach(b=>b.onclick=()=>step(+b.dataset.goto));
