 const fi=$("w11f");if(fi)fi.onchange=async()=>{const st=$("w11phs");const files=[...fi.files].slice(0,6-(s.photos||[]).length);if(!files.length)return;if(!m){st.textContent="Photos upload after you sign in. Your request is saved, so you won't lose anything.";return}
  s.photos=s.photos||[];let n=0;for(const f0 of files){st.textContent=`Uploading ${++n} of ${files.length}…`;try{const f1=typeof r10shrink==="function"?await r10shrink(f0):f0;s.photos.push(await v2upload(f1));keep()}catch(err){toast(err.message,"err")}}st.textContent="";const y=scrollY;render();scrollTo(0,y)};
 const bk=$("w11Back");if(bk)bk.onclick=()=>step(Math.max(0,(s.step||0)-1));
